using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CastleSiegeTests
{
 internal static readonly EntityId Home=new("site:kyoto"),Site=new("site:akutagawa"),Owner=new("created:siege-house"),Defender=new("created:keep-house");
 internal static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 internal static WorldSession Start(bool march=true){var lord=NewGameWorldTests.Officer("created:siege-lord",StartTemplate.Daimyo,Home.Value);var other=NewGameWorldTests.Officer("created:keep-lord",StartTemplate.Daimyo,Site.Value);var setup=NewGameWorldTests.Setup([lord,other],[new(lord.Id,Owner.Value,[Home.Value],false),new(other.Id,Defender.Value,[Site.Value],false)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,lord.Id,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,voyageRules:VoyageExpense.Standard,economyPolicy:HouseSuccession.Policy,territoryPolicy:CastleSiege.Policy,battlefieldPolicy:BattlefieldRules.Policy));Good(s.DecideFactionStance(new(new("decision:siege-hostile"),FactionStanceAction.DeclareHostile,Owner,Defender,0,86400*30),s.PlayerControl,s.Revision));Good(s.DecideNewMilitary(new(new("request:siege-duty"),NewMilitaryAction.Request){AuthorityPolicy=NewGameMilitary.AuthorityContract,LedgerPolicy=NewGameMilitary.LedgerIdentityContract},s.PlayerControl,s.Revision));NewGameWorldTests.At(s,2);BattlefieldRulesTests.Open(s);BattlefieldRulesTests.Military(s,NewMilitaryAction.Accept);NewGameWorldTests.At(s,4);BattlefieldRulesTests.Open(s);BattlefieldRulesTests.Military(s,NewMilitaryAction.Pickup);Good(s.ManageMilitaryRice(new(new("request:siege-food"),s.MilitaryEconomyView()!.Depot,120),s.PlayerControl,s.Revision));BattlefieldRulesTests.Military(s,NewMilitaryAction.Load,NewGameMilitary.Capacity);if(march){Good(s.ManageArmyRoad(new(new("request:siege-march"),ArmyRoadAction.March,Site),s.PlayerControl,s.Revision));NewGameWorldTests.At(s,7);var j=s.DiagnosticSnapshot().Branches!.Journeys.Last();NewGameWorldTests.At(s,j.Legs[^1].EndAt+2);BattlefieldRulesTests.Military(s,NewMilitaryAction.Deploy);}return s;}
 static SiegeInput Input(WorldSession s,SiegeAction action,EntityId? root=null,CastleSection? district=null)=>new(new("request:siege/"+s.Revision),action,Site,root,district);
 [Fact]public void AssaultNeedsRealArrivalAndOrderedDistrict(){var s=Start(false);Assert.Equal(ResultCode.NotAvailable,s.ManageSiege(Input(s,SiegeAction.Begin),s.Revision).Code);}
 [Fact]public void StormConsumesFieldFoodAndRestoresMidAssaultThenHandsOverGateAndKeep(){var s=Start();var begin=Input(s,SiegeAction.Begin);Good(s.ManageSiege(begin,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageSiege(Input(s,SiegeAction.Assault,begin.Id,CastleSection.Keep),s.Revision).Code);var outer=Input(s,SiegeAction.Assault,begin.Id,CastleSection.OuterMoat);Good(s.ManageSiege(outer,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageSiege(outer,s.Revision).Code);long end=s.Seconds+60,food=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;NewGameWorldTests.At(s,end-30);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"siege-check-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId);var host=new WorldSessionHost(new WorldSession(w));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current}){NewGameWorldTests.At(x,end);Assert.Contains(x.DiagnosticSnapshot().Sieges!.Orders,o=>o.Outcome=="区画を確保");Assert.True(NewGameMilitary.View(x.DiagnosticSnapshot()).Carry<food);Good(x.ManageSiege(Input(x,SiegeAction.Parley,begin.Id),x.Revision));Good(x.ManageSiege(Input(x,SiegeAction.DeliverGate,begin.Id),x.Revision));Good(x.ManageSiege(Input(x,SiegeAction.DeliverKeep,begin.Id),x.Revision));}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal("本丸を占有",s.DiagnosticSnapshot().Sieges!.Orders.Last().Outcome);}
 [Fact] public void SupplyUnloadsAtArrivalOnceAfterRestoringAnUnderwayShip(){
  EntityId source=new("site:sakai"),target=new("site:sumoto");
  var lord=NewGameWorldTests.Officer("created:port-lord",StartTemplate.Daimyo,source.Value);
  var setup=NewGameWorldTests.Setup([lord],[new(lord.Id,"created:port-house",[source.Value,target.Value],false)]);
  var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,lord.Id,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy,territoryPolicy:CastleSiege.Policy));
  Good(s.StartPublicWork(new(new("request:port-work"),source,WorksKind.Port),s.Revision));NewGameWorldTests.At(s,7*86400);
  Good(s.StartPublicWork(new(new("request:ship-build"),source,WorksKind.TradeShip),s.Revision));NewGameWorldTests.At(s,21*86400);
  var ship=Assert.Single(PublicWorks.Ships(s.DiagnosticSnapshot()),x=>x.Port==source);Good(s.MaintainPublicShip(new("request:care"),ship.Id,s.Revision));
  var send=new FleetInput(new("request:send"),FleetAction.SendSupply,ship.Id,source,target,15);
  Good(s.ManageSiegeFleet(send,s.Revision));var root=Assert.Single(s.DiagnosticSnapshot().Sieges!.Fleets);
  NewGameWorldTests.At(s,root.Arrive-1);s.SetPaused(true);var w=s.DiagnosticSnapshot();
  var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"fleet-check-"+Guid.NewGuid().ToString("N")),w.Definitions);
  store.Save(s,"manual",w.WorldId);var host=new WorldSessionHost(new WorldSession(w));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));
  foreach(var x in new[]{s,host.Current}){NewGameWorldTests.At(x,root.Arrive);var delivered=Assert.Single(x.DiagnosticSnapshot().Sieges!.Fleets,q=>q.Input.Action==FleetAction.Unload);Assert.Equal(root.Arrive,delivered.At);Assert.Equal(15,SiegeFleet.CastleRiceAt(x.DiagnosticSnapshot(),target,x.Seconds,x.Revision+1));NewGameWorldTests.At(x,root.Home);Assert.Single(x.DiagnosticSnapshot().Sieges!.Fleets,q=>q.Input.Action==FleetAction.Dock);}
  Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));
 }
}
